import { getPersons } from "../components/apiutils";
import Nav from "../components/Nav";
import {useState,useEffect} from "react";


export default function UserMgmt(){
    const [users, setUsers] = useState([]);
    useEffect(()=>{
        getPersons()
        .then((users)=>{
            setUsers(users)
        })
    },[]);

    return <>
    <Nav>
        User Management Dashboard
    </Nav>
    </>
}
